import{_ as t,o as s,c as e,a3 as n}from"./chunks/framework.Dz5Q8p4s.js";const h=JSON.parse('{"title":"BridgeData V2: A Dataset for Robot Learning at Scale","description":"","frontmatter":{"title":"BridgeData V2: A Dataset for Robot Learning at Scale","arxiv":"2308.12952","date":"2023-08-24","authors":"Homer Walke, Kevin Black, Abraham Lee, Moo Jin Kim, Max Du, Chongyi Zheng, Tony Zhao, Philippe Hansen-Estruch, Quan Vuong, Andre He, Vivek Myers, Kuan Fang, Chelsea Finn, Sergey Levine","categories":"cs.RO, cs.LG","topics":"机器人数据集, 大规模模仿学习, 跨机构泛化","outline":[2,2]},"headers":[],"relativePath":"papers/2308.12952.md","filePath":"papers/2308.12952.md","lastUpdated":null}'),o={name:"papers/2308.12952.md"};function r(i,a,l,p,g,d){return s(),e("div",null,[...a[0]||(a[0]=[n('<h1 id="bridgedata-v2-a-dataset-for-robot-learning-at-scale" tabindex="-1">BridgeData V2: A Dataset for Robot Learning at Scale <a class="header-anchor" href="#bridgedata-v2-a-dataset-for-robot-learning-at-scale" aria-label="Permalink to &quot;BridgeData V2: A Dataset for Robot Learning at Scale&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>arXiv</strong></td><td><a href="https://arxiv.org/abs/2308.12952" target="_blank" rel="noreferrer">2308.12952</a></td></tr><tr><td><strong>提交日期</strong></td><td>2023-08-24</td></tr><tr><td><strong>作者</strong></td><td>Homer Walke, Kevin Black, Abraham Lee, Moo Jin Kim, Max Du, Chongyi Zheng, Tony Zhao, Philippe Hansen-Estruch, Quan Vuong, Andre He, Vivek Myers, Kuan Fang, Chelsea Finn, Sergey Levine</td></tr><tr><td><strong>分类</strong></td><td>cs.RO, cs.LG</td></tr><tr><td><strong>一句话</strong></td><td>在一台约 4000 美元的公开 WidowX 机械臂上、跨 24 个场景采集 60,096 条带事后语言标注的操作轨迹（84% 人类遥操作 + 16% 脚本随机策略），并用 6 种目标条件与语言条件方法证明同一份数据能同时服务模仿学习与离线 RL。</td></tr></tbody></table><blockquote><p><strong>所属教程</strong>：<a href="/notes/tutorials/video-for-embodied-ai">视频生成赋能具身智能</a></p></blockquote><h2 id="§-1-—-研究问题与重要性" tabindex="-1">§ 1 — 研究问题与重要性 <a class="header-anchor" href="#§-1-—-研究问题与重要性" aria-label="Permalink to &quot;§ 1 — 研究问题与重要性&quot;">​</a></h2><p>视觉与语言的配方是&quot;高容量模型 + 大而多样的数据&quot;，机器人照抄这个配方的障碍不在算法而在数据。论文把&quot;什么样的数据集才真正有用&quot;拆成四条可操作的要求：其一，<strong>能被采集方之外的实验室复用</strong>——如果数据只覆盖一两个场景，别人想用就得把场景一比一复刻出来；其二，<strong>任务与环境覆盖面足够广</strong>，使学到的策略能迁移到新实验室；其三，<strong>支持灵活的任务条件</strong>，目标图像与自然语言都行；其四（这一条最容易被忽略），<strong>同一环境里必须包含多个可行任务</strong>，否则策略可以从初始观测直接推断任务是什么，多任务条件形同虚设。第四条直接决定了采集协议：不能像初代 Bridge 那样为一小组预定义任务采数据，而要在同一个场景里做任何可行的事。</p><h2 id="§-2-—-前人工作与不足" tabindex="-1">§ 2 — 前人工作与不足 <a class="header-anchor" href="#§-2-—-前人工作与不足" aria-label="Permalink to &quot;§ 2 — 前人工作与不足&quot;">​</a></h2><p>单行为大数据集（抓取、推、戳、绳操作）与单场景多任务数据集（MIME 8.3k/12 技能/1 环境，RoboTurk 2.1k/2/1，BC-Z 26k/3/1）都因环境数太少而难以被别人复用。RoboNet 有 162k 轨迹、10 个环境，但全是脚本采集且无语言标注。MT-Opt 有 80 万条但数据不公开。RT-1 有 130k 轨迹与语言标注，问题在于机器人是专有的、数据也不公开——学术实验室复现不了。初代 Bridge Dataset 是 7.2k 轨迹、4 个技能、12 个环境，机器人公开且有语言，但技能少、且是按预定义任务采的。同期的 RH20T（13k 轨迹、41 技能、50 环境）与 RoboSet（98.5k、6 技能、11 环境，71% 脚本）在规模与多样性上各有优势，作者对它们的区分点不是数据本身，而是<strong>评测的完备性</strong>：几乎所有先前数据集都只被一到两种方法验证过，因此无从判断它们是否真的能服务假设不同的算法族。</p><h2 id="§-3-—-重建作者的思考路径" tabindex="-1">§ 3 — 重建作者的思考路径 <a class="header-anchor" href="#§-3-—-重建作者的思考路径" aria-label="Permalink to &quot;§ 3 — 重建作者的思考路径&quot;">​</a></h2><p>先算一笔账：要让别的实验室能用，机器人必须便宜且公开可买——WidowX 250 整套约 4000 美元、两周内可到货，这条硬约束确定后，采集吞吐就成了瓶颈。人类遥操作很慢，怎么提速？两个办法。第一，<strong>取消重置</strong>：不要求每条轨迹之间把物体与机器人复位，改为每 50 条才随机化相机位姿、换掉场景里的物体、挪动工作空间相对机器人的位置——这既省时间又天然制造了视角与布局的多样性。第二，<strong>取消现场标注</strong>：采集时不给轨迹起任务名，事后用众包平台补语言描述，并特别要求标注者写清被移动物体的最终位置。第三个提速点来自对技能分布的观察：pick-and-place 是最基础也最通用的技能，而它可以用一个高度随机化的脚本策略自动采——该脚本经常失败，但对离线 RL 这类能吃次优数据的方法反而是资源。于是数据被分成 50,365 条人类示范加 9,731 条脚本轨迹，用户可自行选择是否使用后者。</p><h2 id="§-4-—-核心-intuition" tabindex="-1">§ 4 — 核心 Intuition <a class="header-anchor" href="#§-4-—-核心-intuition" aria-label="Permalink to &quot;§ 4 — 核心 Intuition&quot;">​</a></h2><p>数据集的价值不由轨迹条数决定，而由&quot;别人能不能在自己实验室直接拿来用&quot;决定。要做到这一点，就得同时压低硬件门槛（4000 美元的公开机械臂）、拉高场景多样性（24 个场景而非 1 个），并且在同一个场景里采集多个可行任务，逼迫策略去读任务指令而不是去猜。</p><h2 id="§-5-—-具体方法与完整-pipeline" tabindex="-1">§ 5 — 具体方法与完整 Pipeline <a class="header-anchor" href="#§-5-—-具体方法与完整-pipeline" aria-label="Permalink to &quot;§ 5 — 具体方法与完整 Pipeline&quot;">​</a></h2><p>一次采集会话的完整形态：</p><ul><li><strong>硬件</strong>：WidowX 250 机械臂，一台固定在肩上方的 RGB-D 相机、两台位姿在采集中被随机化的 RGB 相机、一台腕部 RGB 相机；图像存为 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">640</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">480</span></span></span></span>，控制频率 5 Hz，用 VR 手柄遥操作。</li><li><strong>场景</strong>：例如摆一个厨房场景，放若干食材、餐具与一个抽屉。采集者做任何可行的事——开抽屉、把餐具放进水槽等——不预设任务清单。</li><li><strong>随机化节奏</strong>：轨迹之间不复位；每 50 条随机化相机位姿、更换物体、挪动工作空间。</li><li><strong>自动采集</strong>：另用一个高度随机化的脚本 pick-and-place 策略自动跑，补 9,731 条（占 16%）。</li><li><strong>事后标注</strong>：众包描述每条轨迹在做什么，强调被移动物体的最终位置。</li><li><strong>组成</strong>：13 个技能（pick-and-place、推、重定向、开关门抽屉、擦拭、叠布、堆块、拧旋钮、拨开关、开水龙头、拉拉链、用工具扫颗粒物等）、24 个场景（其中 7 个是不同的玩具厨房）、100 多个物体，共 60,096 条轨迹。</li></ul><p>评测时统一用<strong>肩上方那一路视角</strong>，观测降到 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">128</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">128</span></span></span></span>（RT-1 用 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">320</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">256</span></span></span></span>），动作是 7 维：6 维相对末端位姿增量加 1 维离散夹爪。评测的六个方法覆盖了目标条件（GCBC / 扩散 GCBC / ACT / Contrastive RL）与语言条件（LCBC / RT-1）两类，差异集中在策略表达能力、是否用观测历史、动作是否离散化、以及是否预测动作块。</p><h2 id="§-6-—-核心数学推导" tabindex="-1">§ 6 — 核心数学推导 <a class="header-anchor" href="#§-6-—-核心数学推导" aria-label="Permalink to &quot;§ 6 — 核心数学推导&quot;">​</a></h2><p>本文无形式化数学推导，跳过。（论文是数据集与实证研究论文，六个被评测方法的目标函数均直接沿用各自原文，正文未给出新的推导。）</p><h2 id="§-7-—-实验设计与结论" tabindex="-1">§ 7 — 实验设计与结论 <a class="header-anchor" href="#§-7-—-实验设计与结论" aria-label="Permalink to &quot;§ 7 — 实验设计与结论&quot;">​</a></h2><p><strong>问题一：能学出多广的技能？</strong> 表 2 在训练分布内的 8 个任务上各跑 10 次。均值是 GCBC 0.49、D-GCBC 0.49、ACT 0.41、CRL 0.42、LCBC 0.23、RT-1 0.49。四个目标条件方法彼此接近；语言侧 RT-1 显著优于 LCBC，作者归因于更大的输入分辨率、动作离散化与观测历史的组合。逐任务看差异很大：开抽屉 RT-1 满分 1.0，而堆积木与玉米入锅两项 RT-1 是 0.0；翻锅与茄子入锅几乎所有方法都在 0.0–0.4。</p><p><strong>问题二：能泛化到新物体与新环境吗？</strong> 表 3 的六个任务分别是&quot;未见物体+已见环境&quot;、&quot;未见物体+未见环境&quot;、&quot;已见物体+未见环境&quot;。均值 GCBC 0.60、D-GCBC 0.55、ACT 0.28、CRL 0.52、LCBC 0.08、RT-1 0.50。这里有一个论文未讨论的反常：<strong>六个方法里有四个在&quot;未见&quot;任务集上的平均成功率高于&quot;已见&quot;任务集</strong>（GCBC 0.49→0.60、D-GCBC 0.49→0.55、CRL 0.42→0.52、RT-1 0.49→0.50），只有 ACT 与 LCBC 下降。语言条件方法在含未见物体的任务上尤其吃力，因为这些物体名从未在数据里被 ground 过（LCBC 在三项上直接为 0）。</p><p><strong>问题三：别的机构能用吗？</strong> 表 4 让另一家机构搭同款机器人、零样本评测同样三个任务。均值 Lab 1 → Lab 2 分别是 GCBC 0.30→0.13、D-GCBC 0.23→0.13、ACT 0.03→0.10、CRL 0.13→0.20、LCBC 0.13→0.03、RT-1 0.47→0.40。作者的结论是&quot;都拿到了非零成功率&quot;，这是准确的；但要注意 ACT 与 CRL 在 Lab 2 反而更高，且绝对数值普遍很低（三个任务恰是表 2 里最难的三个），每格只有 10 次试验。</p><p><strong>问题四：规模与多样性值多少？</strong> 模型容量与数据量的两条曲线在图 5 中呈单调上升，但论文只给了曲线、未给数值。技能多样性那一组给了明确数字：在轨迹数基本相同（28k vs 27k）的前提下，只含 3 个技能（pick-and-place、推、擦拭）的数据训出的策略在一个未见 pick-and-place 任务上成功率 0.30，而含全部 13 个技能的是 0.65，每个策略跑 20 次。这条把 RT-1 关于<strong>物体</strong>多样性的结论推广到了<strong>技能</strong>多样性。</p><p>作者在 Limitations 里承认三点：任务普遍是低精度的，不涉及力控、动态或工业级低容差插装；数据全部在单一机构采集；以及标准化到同一款机器人对别的实验室仍可能是负担。</p><h2 id="§-8-—-take-aways" tabindex="-1">§ 8 — Take-aways <a class="header-anchor" href="#§-8-—-take-aways" aria-label="Permalink to &quot;§ 8 — Take-aways&quot;">​</a></h2><p><strong>5 句话版</strong>：机器人要复制&quot;大数据 + 大模型&quot;的配方，卡点在数据集的可复用性而非算法。BridgeData V2 用一台 4000 美元的公开机械臂，在 24 个场景采了 60,096 条轨迹，其中 84% 人类遥操作、16% 由随机化脚本自动采集，全部配事后众包语言标注。采集协议的关键设计是&quot;同一场景里做任何可行的事&quot;，这样多任务策略必须读任务指令而不能靠初始观测猜任务。六种假设各异的方法（含目标条件 BC、扩散 BC、ACT、对比 RL、语言 BC、RT-1）都能在这份数据上训出可用策略，并在另一家机构零样本拿到非零成功率。在轨迹数持平的对照下，13 个技能的数据比 3 个技能的数据把未见 pick-and-place 任务的成功率从 0.30 提到 0.65。</p><p><strong>3 句话版</strong>：把硬件门槛压到 4000 美元、把场景数提到 24、把语言标注做成事后众包，数据集才可能被别人真正用起来。同一份数据被六种假设不同的方法验证，这在此前的机器人数据集里罕见。技能多样性本身就是泛化的来源，而不只是数据量。</p><p><strong>1 句话版</strong>：一份为&quot;被别人复用&quot;而设计的大规模真机操作数据集，并用六种方法证明了这个设计目标基本达成。</p><h2 id="§-9-—-最脆弱的假设" tabindex="-1">§ 9 — 最脆弱的假设 <a class="header-anchor" href="#§-9-—-最脆弱的假设" aria-label="Permalink to &quot;§ 9 — 最脆弱的假设&quot;">​</a></h2><p>最要害的一条是：<strong>在 24 个自建场景里采数据，足以让策略跨机构泛化</strong>。这是整个数据集设计的立论基础——正是这一条推导出了&quot;要 24 个环境而不是 1 个&quot;，也正是这一条支撑了&quot;别的研究者可以直接拿来训&quot;的价值主张。但这 24 个场景全部由同一个实验室搭建（其中 7 个是玩具厨房，其余是各种桌面、独立玩具水槽、玩具洗衣机），用同一款机器人、同一套相机安装惯例、同一批采集者、同一个 5 Hz 控制频率。这些共享的隐性因素恰恰是跨机构迁移时最容易变的东西。论文为该假设提供的证据只有表 4：<strong>三个任务、单一外部实验室、每格 10 次试验</strong>，且这三个任务是表 2 里最难的三个，绝对成功率落在 0.03–0.47 之间；更麻烦的是六个方法里有两个在新实验室反而更好，说明这个规模下的测量已经被噪声主导。作者自己在 Limitations 里承认&quot;数据全部在单一机构采集&quot;。如果这一假设不成立，那么 BridgeData V2 的定位就要从&quot;跨机构可复用的基础数据&quot;退回到&quot;一个特别多样的单机构数据集&quot;，其真正价值会转移到后来的多机构联合数据集方向上。</p><h2 id="§-10-—-最小复现实验" tabindex="-1">§ 10 — 最小复现实验 <a class="header-anchor" href="#§-10-—-最小复现实验" aria-label="Permalink to &quot;§ 10 — 最小复现实验&quot;">​</a></h2><p>不需要自己采数据，也不需要跑满六个方法。用公开的 BridgeData V2 与预训练模型做一个<strong>协变量剥离实验</strong>：固定 GCBC 与预训练权重，在评测时逐项引入训练分布里存在但被固定住的变量——（a）把肩上方相机的高度/俯仰改变 15°；（b）把控制频率从 5 Hz 改到 3 Hz 与 10 Hz；（c）换一套不同色温的照明。每种改动下在同样三个任务上各跑 20 次，记录成功率下降幅度。判据很直接：若相机位姿扰动带来的下降幅度与表 4 中跨机构的下降幅度相当，那么&quot;跨机构差距&quot;主要就是相机安装差异，而这可以靠数据增广或位姿标定廉价地补上；若跨机构的下降远大于三项单因素扰动之和，说明存在论文未识别的领域偏移源，值得优先排查。这个实验一周内可完成，只需要一台 WidowX。</p><h2 id="§-11-—-最强反例设计" tabindex="-1">§ 11 — 最强反例设计 <a class="header-anchor" href="#§-11-—-最强反例设计" aria-label="Permalink to &quot;§ 11 — 最强反例设计&quot;">​</a></h2><p>最有力的攻击针对表 3 的&quot;泛化&quot;结论。论文用&quot;在未见物体/未见环境的任务上仍有非零成功率&quot;论证数据支持广泛泛化，但表 3 的平均成功率对四个方法而言<strong>高于</strong>表 2 的已见任务平均。如果泛化真的有代价，这个方向就不该出现。最简洁的替代解释是：两组任务的难度根本没有对齐——表 2 里塞进了翻锅、茄子入锅这类几乎所有方法都做不好的任务（多个方法 0.0–0.2），而表 3 的六项以擦桌子、把蘑菇放进锅、把勺子放到布上为主，本身就更容易。检验方法是做一个<strong>难度配对</strong>的评测：为表 3 的每个未见任务，构造一个使用相同技能、相同物体几何尺度、只是物体与场景都在训练分布内的对照任务，两两配对各跑 20 次，报告配对差值而不是各自均值。若配对差值接近 0，&quot;广泛泛化&quot;成立；若配对差值显著为负而未配对均值仍显示&quot;未见更高&quot;，则表 3 的结论完全是任务选择的产物。第二个攻击点在技能多样性那一组：0.30 vs 0.65 是 20 次试验（即 6/20 与 13/20），二项分布下 95% 置信区间宽约 ±0.21，两者虽不重叠但边际很窄；而且 3 技能子集恰好去掉了叠布、堆块、开抽屉这些需要精细腕部姿态的技能，&quot;多样性有益&quot;与&quot;这三类技能特别有助于抓取姿态&quot;是两个不同的结论，论文没有区分。</p><h2 id="§-12-—-follow-up-research-idea" tabindex="-1">§ 12 — Follow-up Research Idea <a class="header-anchor" href="#§-12-—-follow-up-research-idea" aria-label="Permalink to &quot;§ 12 — Follow-up Research Idea&quot;">​</a></h2><p>BridgeData V2 把数据采集当作一个<strong>离线的、一次性的</strong>工程：先决定好协议，采满 6 万条，然后交给算法。但论文自己最有信息量的结果恰恰指向另一个方向——技能多样性在轨迹数持平时把成功率翻了一倍，说明&quot;采什么&quot;比&quot;采多少&quot;更值钱。那么真正该被研究的对象就不是数据集本身，而是<strong>采集策略</strong>：给定固定的人力预算，下一条轨迹应该在哪个场景、用哪个技能、配哪个物体采？可借鉴的相邻领域工具是实验设计与主动学习里的信息增益准则，具体到这里可以用一个在已有数据上训好的策略的<strong>失败模式分布</strong>来驱动：在留出场景上跑策略，把失败按技能与物体几何聚类，把下一批采集配额按失败密度分配。这套流程与 BridgeData V2 的采集协议高度兼容，因为它本来就是&quot;每 50 条换一次场景配置&quot;的分批形态。第一个实验规模很小：从现有数据里划出 20k 条作为种子，然后用两种方式各追加 8k 条——随机分层追加 vs 按失败密度定向追加——在同一组留出任务上比较最终成功率。若定向追加的收益显著大于随机追加，那么&quot;机器人数据集&quot;就应该被重新理解为一个闭环过程而不是一个静态产物，这也为 <a href="/notes/papers/2302.00111">UniPi</a> 那类以生成模型消费机器人视频的路线提出了一个新问题：生成模型的失败模式是否与策略的失败模式重合，从而可以共用同一套采集预算分配。</p>',35)])])}const c=t(o,[["render",r]]);export{h as __pageData,c as default};
